        if o.get('name')=='seurat2anndata' or o.get('value')=='seurat2anndata':
            print('FOUND at', path, json.dumps(o, indent=2)[:4000])
        for k,v in o.items():
            walk(v, path+'/'+str(k))
    elif isinstance(o, list):
        for i,v in enumerate(o):
            walk(v, path+'['+str(i)+']')
walk(d)
