#!/usr/bin/env Rscript

suppressPackageStartupMessages({
  library(Matrix)
  library(jsonlite)
})

args <- commandArgs(trailingOnly = TRUE)
if (length(args) < 3L || length(args) > 4L) {
  stop("usage: inspect_rds.R INPUT.rds REPORT.json METADATA.tsv [MEMBER]")
}

input_path <- args[[1L]]
report_path <- args[[2L]]
metadata_path <- args[[3L]]
member <- if (length(args) == 4L) args[[4L]] else NULL
object <- readRDS(input_path)

bounded <- function(values, limit = 100L) {
  if (is.null(values)) character() else head(as.character(values), limit)
}

describe <- function(value) {
  dimensions <- dim(value)
  list(
    class = unname(as.character(class(value))),
    type = typeof(value),
    is_s4 = isS4(value),
    length = length(value),
    dimensions = if (is.null(dimensions)) NULL else unname(as.integer(dimensions)),
    names = bounded(names(value)),
    slots = if (isS4(value)) bounded(slotNames(value)) else character(),
    attributes = bounded(names(attributes(value)))
  )
}

available_members <- unique(c(
  if (isS4(object)) slotNames(object) else character(),
  names(object)
))

get_member <- function(value, name) {
  if (isS4(value) && name %in% slotNames(value)) {
    return(slot(value, name))
  }
  if (!is.null(names(value)) && name %in% names(value)) {
    return(value[[name]])
  }
  stop(sprintf("member not found: %s", name))
}

candidate_names <- intersect(
  c("meta.data", "colData", "metadata", "pData", "phenoData", "obs"),
  available_members
)
candidate_descriptions <- setNames(
  lapply(candidate_names, function(name) describe(get_member(object, name))),
  candidate_names
)

report <- list(
  object = describe(object),
  available_members = bounded(available_members),
  metadata_candidates = candidate_descriptions
)
writeLines(
  toJSON(report, auto_unbox = TRUE, pretty = TRUE, null = "null"),
  report_path
)

if (is.null(member)) {
  write.table(
    data.frame(status = "not_requested", detail = "inspect report first"),
    metadata_path,
    sep = "\t",
    quote = FALSE,
    row.names = FALSE
  )
} else {
  metadata <- tryCatch(
    as.data.frame(get_member(object, member)),
    error = function(error) {
      stop(sprintf("member %s is not tabular: %s", member, error$message))
    }
  )
  row_ids <- rownames(metadata)
  if (is.null(row_ids)) {
    row_ids <- as.character(seq_len(nrow(metadata)))
  }
  write.table(
    data.frame(row_id = row_ids, metadata, check.names = FALSE),
    metadata_path,
    sep = "\t",
    quote = FALSE,
    row.names = FALSE,
    na = "NA"
  )
}

